import { useState } from 'react';

export function CheckoutForm({ onSubmit }: { onSubmit: (data: any) => void }) {
  const [form, setForm] = useState({
    firstName: '', lastName: '', email: '',
    address1: '', address2: '', city: '',
    state: '', zip: '', country: '',
    cardNumber: '', cardExp: '', cardCvc: '',
    phone: '', notes: '', promoCode: ''
  });

  const handleChange = (field: string, value: string) => {
    setForm(prev => ({ ...prev, [field]: value }));
  };

  return (
    <form onSubmit={(e) => { e.preventDefault(); onSubmit(form); }}>
      <input value={form.firstName} onChange={e => handleChange('firstName', e.target.value)} />
      <input value={form.email} onChange={e => handleChange('email', e.target.value)} />
      {/* ... 13 more fields like this */}
      <button type="submit">Submit</button>
    </form>
  );
}
```

